use consumer_behavior;

select * from customer_behavior;

-- 1. Revenue Analysis — Compared total revenue generated by male and female customers.
select gender, SUM(purchase_amount) as revenue
from customer_behavior
group by gender;


-- 2. Discount & Spending Analysis — Identified discount users whose purchase amounts were at or above the overall average.
select customer_id, purchase_amount 
from customer_behavior 
where discount_applied = 'Yes' and purchase_amount >= (select AVG(purchase_amount) from customer);


-- 3. Product Rating Analysis — Ranked the top 5 products by average review rating.
select top 5 item_purchased, round(avg(review_rating::numeric),2) as "Average Product Rating"
from customer_behavior
group by item_purchased
order by avg(review_rating) desc;


-- 4. Shipping Analysis — Compared average purchase amounts for Standard and Express shipping.
select shipping_type, 
ROUND(AVG(purchase_amount),2)
from customer_behavior
where shipping_type in ('Standard','Express')
group by shipping_type;

-- 5. Subscription Analysis- compare customer counts, average spendin and total revenue 
--    between subscribers and non subscribers
   
   select subscription_status as subscribed, count(customer_id) as customer_count,
          avg(purchase_amount) as average_spending,
          sum(purchase_amount) as total_revenue
   from customer_behavior
          group by subscription_status;

-- 6. Discount Dependency Analysis — Identified the top 5 products by percentage of purchases with discounts applied.

SELECT top 5 item_purchased,
       100*sum(
             case when discount_applied = 'Yes' then 1 else 0 end)/count(*) as discount_rate
FROM customer_behavior
GROUP BY item_purchased
ORDER BY discount_rate DESC;

-- 7. Customer Segmentation — Classified customers into New, Returning, and Loyal segments based on previous purchases.

with customer_type as (
SELECT customer_id, previous_purchases,
CASE 
    WHEN previous_purchases = 1 THEN 'New'
    WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
    ELSE 'Loyal'
    END AS customer_segment
FROM customer_behavior)
select customer_segment,count(*) AS "Number of Customers" 
from customer_type 
group by customer_segment;


-- 8. Product Popularity Analysis — Identified the top 3 most purchased products within each category.
WITH item_counts AS (
    SELECT category,
           item_purchased,
           COUNT(customer_id) AS total_orders,
           ROW_NUMBER() OVER (PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS item_rank
    FROM customer_behavior
    GROUP BY category, item_purchased
)
SELECT item_rank,category, item_purchased, total_orders
FROM item_counts
WHERE item_rank <=3;


-- 9. Repeat Buyer Analysis — Compared subscription status among customers with more than 5 previous purchases.
SELECT subscription_status,
       COUNT(customer_id) AS repeat_buyers
FROM customer_behavior
WHERE previous_purchases > 5
GROUP BY subscription_status;


-- 10. Age Group Revenue Analysis — Compared total revenue across customer age groups.
SELECT 
    age_group,
    SUM(purchase_amount) AS total_revenue
FROM customer_behavior
GROUP BY age_group
ORDER BY total_revenue desc;